// Тикет #6a86f7fb5ce7 «פיתוח: תוספות עונתיות בתפילה ובלוח», проверен на web 07.10.2026 (session.json: «соответствует F-49 AC1, AC2, AC4»).
// Опора: F-49 AC4 «תוספת עונתית מוצגת רק בתקופה שבה היא רלוונטית לפי הלוח העברי»; реджект 24.09 п.1 (неактуальные — свёрнуты «לא נאמר היום»),
// п.2 (карточка «תוספות בתפילה» во всех נוסחים). Скрины: 6a86f7fb-r7-1-amida-today-mincha-ashk («בקיץ — לא נאמר היום · הצגה»),
// 6a86f7fb-r7-8a-shacharit-amida-28.09 (карточка «תוספות בתפילה»: «יעלה ויבוא — סוכות», «מוריד הטל — ימות החמה»).
// Дата НЕ подменяется (реальный день устройства). Ожидание по יעלה ויבוא — из Hebcal converter (ראש חודש / חול המועד → строка
// «יעלה ויבוא — …» в карточке, обычный будний день → её нет). Около שקיעה (день меняется по городу) и в праздник — только структура.
import { expect } from '@wdio/globals';
import { byText, byTextMatches, tapText, expectVisibleText, scrollToText, pageCounter } from '../../helpers/ui.ts';
import { openPrayer, goToPage } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';
import { ensureNusach, nusachHeader, shown } from '../_lib/app-0710.ts';

type Expectation = 'yaaleh' | 'no-yaaleh' | 'unknown';

/** Сегодняшний еврейский день по Hebcal: нужна ли строка «יעלה ויבוא» в карточке. Ненадёжно → 'unknown'. */
async function yaalehExpectation(): Promise<Expectation> {
  const now = new Date();
  const parts = Object.fromEntries(
    new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Jerusalem', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', hourCycle: 'h23' })
      .formatToParts(now).map((p) => [p.type, p.value]),
  );
  const hour = Number(parts.hour);
  if (hour < 7 || hour >= 16) return 'unknown';              // рядом с שקיעה день мог смениться — не гадаем
  try {
    const url = `https://www.hebcal.com/converter?cfg=json&date=${parts.year}-${parts.month}-${parts.day}&g2h=1&strict=1`;
    const res = await fetch(url, { signal: AbortSignal.timeout(10000) });
    if (!res.ok) return 'unknown';
    const data = (await res.json()) as { events?: string[] };
    const events = data.events ?? [];
    if (events.some((e) => /Rosh Chodesh|CH''M/.test(e))) return 'yaaleh';
    if (events.some((e) => /Sukkot|Pesach|Shavuot|Rosh Hashana|Shmini Atzeret|Simchat Torah|Yom Kippur/.test(e))) return 'unknown';
    return 'no-yaaleh';
  } catch {
    return 'unknown';
  }
}

/** Пройти страницы молитвы с начала до страницы с карточкой «תוספות בתפילה» (עמידה). */
async function goToAdditionsCard() {
  const total = Number((await pageCounter()).split(' ')[2]);
  await goToPage(1, total);
  for (let i = 1; i <= total; i++) {
    if (await shown(byText('תוספות בתפילה'))) return;
    await scrollToText('המשך');
    await tapText('המשך');
    await expect(byTextMatches(`${i + 1} מתוך ${total}`)).toBeDisplayed();
  }
  throw new Error('Карточка «תוספות בתפילה» не найдена ни на одной странице');
}

/** Строка карточки «יעלה ויבוא — <повод>» (не свёрнутая «… — לא נאמר היום»). */
const yaalehCardLine = () => byTextMatches('יעלה ויבוא — (?!לא נאמר).*');

async function checkCardToday(expectation: Expectation) {
  await goToAdditionsCard();
  await expectVisibleText('תוספות בתפילה');
  if (expectation === 'yaaleh') await expect(yaalehCardLine()).toBeDisplayed();
  if (expectation === 'no-yaaleh') await expect(yaalehCardLine()).not.toBeDisplayed();
  // Неактуальная сегодня תוספת не удалена, а свёрнута «… — לא נאמר היום · הצגה».
  await scrollToText('לא נאמר היום', 15);
  await expect(byTextMatches('.* — לא נאמר היום.*')).toBeDisplayed();
}

describe('תוספות עונתיות: сегодня', () => {
  afterEach(async () => { await toHome(); });

  it('SE-01 מנחה сегодня: карточка «תוספות בתפילה» по еврейскому дню (Hebcal), неактуальные свёрнуты «לא נאמר היום» — в אשכנזי и ספרדי #6a86f7fb5ce7 @prod-safe', async () => {
    const expectation = await yaalehExpectation();
    console.warn(`[SE-01] ожидание по Hebcal: ${expectation}`);

    await openPrayer('mincha_ashkenaz', 'מנחה');
    await ensureNusach('אשכנזי');
    await checkCardToday(expectation);

    // Карточка есть и в ספרד (реджект 24.09 п.2). Вернуть אשכנזי в конце.
    try {
      await ensureNusach('ספרדי');
      await checkCardToday(expectation);
    } finally {
      await ensureNusach('אשכנזי');
    }
    await expect(nusachHeader('אשכנזי')).toBeDisplayed();
  });
});
